%
% MATLAB script for plotting the directivity function for
% a pointdriven elastic plate
%
% Parameters:
% f     Frequency
% rho   Density
% c     Speed of Sound
% h     Plate thickness
% E     Young's modulus
% nu    Poisson's ratio
% rhos Plate density
clear
rhos=7700;
cp=5600;
h=0.05;
E=rhos*cp^2;
nu=0.33;
D= E *h^3/(12*(1-nu^2));
rho=1000;
c=1500;
f=8000;
omega=2*pi*f;
k=omega/c
ka=k;
figure(1);
hold off
kxm=2*ka;
nkx=300;
dkx=2*kxm/(nkx-1);
x=[-kxm:dkx:kxm];
y=x;
o=ones(1,nkx);
kx=x' * o;
ky=(y' *o)';
kr=abs(complex(kx,ky));
kf= ((rhos*h+i*rho./sqrt(k^2-complex(kr,0.0).^2))*omega^2/D).^0.25;
kfa=kf*a;
ss=-rho*omega^2./(D*(2*pi)^2 *(complex(kr,0).^4 -kfa.^4));
wavei(dba(ss)',x,y)
shading('flat')
axis('equal')
b=xlabel('k_x')
set(b,'FontSize',16);
b=ylabel('k_y')
set(b,'FontSize',16);
tit=['Point Driven Plate, h =' num2str(h) ', f = ' num2str(f)]
b=title(tit);
set(b,'FontSize',20);
nphi=361;
dphi=2*pi/(nphi-1);
phi=[0:dphi:2*pi];
xx=k*a*cos(phi);
yy=k*a*sin(phi);
hold on
b=plot(xx,yy,'b');
t(b 'Li Width' 3)
